def f(g,tgt=2):
    H=len(g); W=len(g[0]); out=[r[:] for r in g]
    line=None
    for col in set(x for r in g for x in r):
        fr=[r for r in range(H) if all(g[r][c]==col for c in range(W))]
        fc=[c for c in range(W) if all(g[r][c]==col for r in range(H))]
        if len(fr)>len(fc) and len(fr)>0: line=col; break
    else:
        for col in set(x for r in g for x in r):
            fr=[r for r in range(H) if all(g[r][c]==col for c in range(W))]
            fc=[c for c in range(W) if all(g[r][c]==col for r in range(H))]
            if len(fr)>0 or len(fc)>0: line=col; break
    if line is None: return out
    for r in range(H):
        if all(g[r][c]==line for c in range(W)):
            for c in range(W):
                if out[r][c]==line: out[r][c]=tgt
    for c in range(W):
        if all(g[r][c]==line for r in range(H)):
            for r in range(H):
                if out[r][c]==line: out[r][c]=tgt
